    private static int RunActualLegacySelected(IReadOnlyList<ClipRay.PreparedCli.RegisteredCase> tests)
    {
        if (tests.Count == 0) { Console.Error.WriteLine("0 tests collected"); return 2; }
        var failures = 0;
        foreach (var test in tests)
        {
            try { test.Run(); Console.WriteLine($"PASS {test.Name}"); }
            catch (Exception exception) { failures++; Console.Error.WriteLine(FormatFailure(test.Name, exception)); }
        }
        Console.WriteLine($"{tests.Count - failures}/{tests.Count} tests passed");
        return failures == 0 ? 0 : 1;
    }
